import base64
import shutil
import unittest

from cloud_render.chromium_capture import CaptureError, PICTURE, TREE, capture_frame, parse_trace_frame
from cloud_render.wire import Frame
try:
    from playwright.async_api import async_playwright
except ImportError:
    async_playwright = None


# Solid white 1090x760 picture generated by Chromium's cc::DisplayItemList.
SOLID_SKP = bytes.fromhex(
    "736b6961706963746e00000000000000000000000040884400003e440164616572540000000400001e1c0000030000"
    "0000000000000040884400003e440100000050000000180000150100000000000000000000000040884400003e4418"
    "0000150200000000000000000000000040884400003e440400001c7463616604000000000000006366707400000000"
    "796172614800000020746e70020000000000000000008040f7f6763ff7f6763ff7f6763f0000803f01010000000000"
    "0000008040f7f6763ff7f6763ff7f6763f0000803f0103000067756c730000000020666f65"
)


def picture(ref, layer_id, *, pid=1, tid=2, timestamp=1):
    fields = {"snapshot": {"params": {"layer_rect": [0, 0, 1090, 760]},
                           "skp64": base64.b64encode(SOLID_SKP).decode()}}
    if ref:
        fields.update(id=ref, layer_id=layer_id)
    return {"pid": pid, "tid": tid, "ts": timestamp, "name": PICTURE, "args": fields}


def layer(ref, layer_id):
    return {"layer_id": layer_id, "draws_content": 1, "opacity": 1, "effect_tree_index": 1,
            "clip_tree_index": 2, "pictures": [{"id_ref": ref}], "bounds": {"width": 1090, "height": 760},
            "visible_rect": [0, 0, 1090, 760], "layer_quad": [0, 0, 1090, 0, 1090, 760, 0, 760]}


def tree(layers, timestamp=3):
    return {"pid": 1, "tid": 2, "ts": timestamp, "name": TREE, "args": {"layerTreeId": 1, "snapshot": {
        "device_viewport_size": {"width": 1090, "height": 760}, "active_tree": {"layers": layers}}}}


def parse(events):
    return parse_trace_frame(events, process_id=1, width=1090, height=760, sequence=3)


class ChromiumLayerIdentity(unittest.TestCase):
    def test_match_visible_layers_by_identity_and_compositor_paint_order(self):
        first, second = layer("bg", 11), layer("control", 18)
        second["layer_quad"] = [10, 0, 1100, 0, 1100, 760, 10, 760]
        result = parse([picture("control", 18), picture("bg", 11), tree([first, second])])
        self.assertEqual([item.x for item in result.layers], [0, 10])
        self.assertEqual(result.layers[0].skp, SOLID_SKP)

    def test_unresolved_layer_never_borrows_another_process_or_later_snapshot(self):
        scene = tree([layer("bg", 11)])
        for p in [picture("bg", 11, pid=2), picture("bg", 12), picture("other", 11),
                  picture("bg", 11, timestamp=4)]:
            with self.subTest(p=p["args"].get("id")), self.assertRaises(CaptureError):
                parse([p, scene])
        # A changed recording at the same layer ID invalidates the old picture.
        with self.assertRaises(CaptureError):
            parse([picture("bg", 11), scene, tree([layer("new", 11)], timestamp=6)])

    def test_shared_renderer_with_multiple_layer_trees_is_ambiguous(self):
        first = tree([layer("bg", 11)])
        second = tree([layer("bg", 11)], timestamp=4)
        second["args"]["layerTreeId"] = 2
        with self.assertRaises(CaptureError):
            parse([picture("bg", 11), first, second])

    def test_legacy_anonymous_picture_requires_one_visible_layer_and_same_thread(self):
        one = tree([layer("bg", 11)])
        self.assertIsInstance(parse([picture(None, 0), one]), Frame)
        for events in [[picture(None, 0, tid=9), one], [picture(None, 0), picture(None, 0), one],
                       [picture(None, 0), tree([layer("bg", 11), layer("overlay", 12)])]]:
            with self.assertRaises(CaptureError):
                parse(events)

    def test_unrepresentable_compositor_effects_fail_closed(self):
        ordinary = layer("bg", 11)
        for override in [{"opacity": 0.5}, {"pictures": []}, {"clip_tree_index": 4},
                         {"visible_rect": [10, 10, 40, 50]}, {"sorting_context_id": 1},
                         {"layer_quad": [1, 0, 1090, 2, 1090, 760, 0, 760]}]:
            with self.subTest(override=override), self.assertRaises(CaptureError):
                parse([picture("bg", 11), tree([{**ordinary, **override}])])


@unittest.skipUnless(async_playwright and shutil.which("chromium"), "需要 Chromium 与 Playwright")
class IsolatedChromiumCapture(unittest.IsolatedAsyncioTestCase):
    async def test_actual_sandboxed_renderer_static_and_click_update(self):
        async with async_playwright() as playwright:
            browser = await playwright.chromium.launch(executable_path=shutil.which("chromium"),
                                                       headless=True, chromium_sandbox=True)
            context = await browser.new_context(offline=True, viewport={"width": 420, "height": 280})
            page = await context.new_page()
            await page.set_content('<button style="background:red" onclick="this.style.background=\'lime\'">ABC</button>')
            first = await capture_frame(page, 1)
            second = await capture_frame(page, 2)
            self.assertEqual(first.layers, second.layers)
            await page.locator("button").click()
            third = await capture_frame(page, 3)
            self.assertNotEqual(first.layers, third.layers)
            self.assertEqual((third.width, third.height), (420, 280))
            await context.new_page()
            with self.assertRaises(CaptureError):
                await capture_frame(page, 4)
            await browser.close()
